def check(N, M, Edges):
    adj = [[] for _ in range(N + 1)]
    for u, v in Edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * (N + 1)

    def dfs(u, count):
        if count == N:
            return True
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                if dfs(v, count + 1):
                    return True
                visited[v] = False
        return False

    for start in range(1, N + 1):
        visited[start] = True
        if dfs(start, 1):
            return True
        visited[start] = False

    return False
